"""Render a ``cdc_bakeoff.py`` JSON report as ``docs/bench/0.53-cdc.md``.

Every number in the page comes from the report; nothing is typed by hand.
Regenerate with::

    uv run python scripts/bench/cdc_bakeoff.py --out cdc.json --markdown docs/bench/0.53-cdc.md
"""

from __future__ import annotations

HEADER = """# 0.53 CDC bake-off re-run (correct gear table)

<!-- Generated by scripts/bench/cdc_bakeoff.py --markdown; do not edit by hand. -->

The 0.40 bake-off (`docs/bench/0.40-cdc-bakeoff.md`) built its FastCDC gear
table with a fresh `random.Random(40)` per entry, so all 256 entries were equal
and its `cdc-*` rows did not cut on content. Those rows are void. This re-run
uses the gear table that stored data already uses (`opentine/remote/_fastcdc.py`:
one `random.Random(49)` generator, 256 distinct 64-bit entries); the script
refuses to run unless the table hashes to the pinned digest below. A second
script bug is also fixed: the synthetic corpus listed only loose objects, and
`put_run` now writes packs, so run objects were silently missing; the corpus
now lists loose and packed objects (`iter_object_oids`).

**Stored-data chunking is unchanged.** The 0.49 chunker was already correct;
only the bench script was wrong. Chunk boundaries are a stored form (oids,
canonical bytes and wire formats do not depend on them), and no frozen format
or vector changes in 0.53.

**Times are indicative.** Sizes and ratios are deterministic for the pinned
inputs. CPU and latency columns depend on the machine; the number for the
pinned runner (ubuntu-24.04, single-threaded) is produced in CI by the
`CDC bake-off (pinned runner)` job in `.github/workflows/bench.yml`, which
uploads `cdc.json` and `0.53-cdc.md` as artifacts. The table below is the
reference run that generated this file.
"""


def _row(name: str, row: dict) -> str:
    return (
        f"| {name} | {row['bytes']:,} | {row['ratio']} | {row['encode_cpu_s']} "
        f"| {row['access_p50_ms']} | {row['access_p95_ms']} |"
    )


def render(report: dict) -> str:
    """The Markdown page for *report* (an ``opentine-cdc-bakeoff/2`` document)."""
    pin = report["pinned"]
    out = [HEADER, "## Pinned inputs", ""]
    out.append("| Input | Value |")
    out.append("|---|---|")
    for key in ("seed", "runs", "steps", "level", "block_mib", "samples"):
        out.append(f"| {key} | {pin[key]} |")
    out.append(f"| gear table | `{report['gear_sha256']}` (SHA-256 of 256 big-endian u64) |")
    out.append(f"| python | {report['python']} |")
    out.append("")
    out.append(f"Reproduce: `{report['command']}`")
    for label, corpus in report["corpora"].items():
        out += ["", f"## Corpus: {label}", ""]
        out.append(f"{corpus['objects']:,} objects, {corpus['logical_bytes']:,} logical bytes.")
        out += ["", "| Option | Stored bytes | Ratio | Encode CPU s | p50 ms | p95 ms |"]
        out.append("|---|---:|---:|---:|---:|---:|")
        for name, row in corpus.items():
            if isinstance(row, dict):
                out.append(_row(name, row))
    if report.get("gc"):
        out += ["", "## gc end to end", "", "| Mode | Pack bytes | Ratio | Seconds |"]
        out.append("|---|---:|---:|---:|")
        for mode, row in report["gc"].items():
            out.append(f"| {mode} | {row['bytes']:,} | {row['ratio']} | {row['seconds']} |")
    gate = report.get("autopack_gate")
    if gate:
        verdict = "passes" if gate["passes"] else "fails"
        out += [
            "",
            "Autopack gate (p95 with deltas within 1.5x of without): "
            f"{gate['p95_ratio']}x, {verdict}.",
        ]
    out += ["", "## Smallest stored form per corpus (computed)", ""]
    for label, corpus in report["corpora"].items():
        rows = {k: v for k, v in corpus.items() if isinstance(v, dict)}
        best = min(rows, key=lambda k: rows[k]["bytes"])
        full = rows.get("full", rows[best])["bytes"]
        size = rows[best]["bytes"]
        if best == "full":
            out.append(f"- {label}: `full` ({size:,} bytes); no delta or CDC form is smaller")
        else:
            ratio = f"{full / size:.2f}x smaller than `full`"
            out.append(f"- {label}: `{best}` ({size:,} bytes, {ratio})")
    out += [
        "",
        "The 0.40 corpus caveat still applies: no consented real-user corpus exists, so the",
    ]
    out.append("fixture corpus is tiny. Whether local packs adopt CDC is a decision for a later")
    out.append("release; it would be a new stored form and is outside the 0.53 scope.")
    return "\n".join(out) + "\n"
